# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
import torch
import triton
import triton.language as tl

try:
    from triton.runtime import driver as _triton_driver
except Exception:  # pragma: no cover
    _triton_driver = None

MAX_DIMS = 8

# Cache the queried vector-core count per device index. This is an immutable
# device characteristic (not a tensor/input cache); querying it caps the
# launched-program count portably per the B2 requirement.
_VCORE_CACHE = {}


def _num_vectorcore(dev_index):
    cached = _VCORE_CACHE.get(dev_index)
    if cached is not None:
        return cached
    n = None
    if _triton_driver is not None:
        try:
            props = _triton_driver.active.utils.get_device_properties(dev_index)
            n = props.get("num_vectorcore")
            if not n:
                n = props.get("num_aicore")
        except Exception:
            n = None
    if not n or int(n) <= 0:
        n = 20  # conservative fallback if the query is unavailable
    n = int(n)
    _VCORE_CACHE[dev_index] = n
    return n


# ---- persistent in-place kernels (grid capped at <= num_vectorcore) ----
# IMPORTANT: on this Ascend/flagtree backend, reading and writing the SAME
# buffer in one kernel is only correct when the launched-program count does not
# exceed the physical vector-core count. Debug sweeps showed 0 errors up to
# grid == num_vectorcore (40 on the dev device) and heavy corruption once the
# grid exceeds it (64). We therefore cap the grid at num_vectorcore and stride
# by tl.num_programs(0), which both fixes correctness and matches the reference
# memory traffic (one read-read-write pass, no scratch buffer, single launch).


@triton.jit
def _inplace_contig_kernel(A_ptr, B_ptr, numel, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    nprog = tl.num_programs(0)
    step = nprog.to(tl.int64) * BLOCK
    base = pid.to(tl.int64) * BLOCK
    for off0 in range(base, numel, step):
        offs = off0 + tl.arange(0, BLOCK).to(tl.int64)
        mask = offs < numel
        a = tl.load(A_ptr + offs, mask=mask)
        b = tl.load(B_ptr + offs, mask=mask)
        tl.store(A_ptr + offs, (a < b).to(a.dtype), mask=mask)


@triton.jit
def _inplace_scalar_kernel(A_ptr, b_scalar, numel, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    nprog = tl.num_programs(0)
    step = nprog.to(tl.int64) * BLOCK
    base = pid.to(tl.int64) * BLOCK
    for off0 in range(base, numel, step):
        offs = off0 + tl.arange(0, BLOCK).to(tl.int64)
        mask = offs < numel
        a = tl.load(A_ptr + offs, mask=mask)
        tl.store(A_ptr + offs, (a < b_scalar).to(a.dtype), mask=mask)


# ---- two-kernel fallback for the broadcast / non-contiguous path ----
# The strided broadcast case is not covered by the simple linear in-place
# kernel; we keep the proven compute-into-int8-buffer + copy-back design for it.


@triton.jit
def _cmp_strided_kernel(
    A_ptr,
    B_ptr,
    C_ptr,
    numel,
    shape_ptr,
    astride_ptr,
    bstride_ptr,
    BLOCK: tl.constexpr,
    MAX_DIMS: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid.to(tl.int64) * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
    mask = offs < numel
    rem = offs
    a_off = tl.zeros((BLOCK,), dtype=tl.int64)
    b_off = tl.zeros((BLOCK,), dtype=tl.int64)
    for d in range(MAX_DIMS - 1, -1, -1):
        dim_size = tl.load(shape_ptr + d).to(tl.int64)
        a_str = tl.load(astride_ptr + d).to(tl.int64)
        b_str = tl.load(bstride_ptr + d).to(tl.int64)
        coord = rem % dim_size
        rem = rem // dim_size
        a_off += coord * a_str
        b_off += coord * b_str
    a = tl.load(A_ptr + a_off, mask=mask)
    b = tl.load(B_ptr + b_off, mask=mask)
    res = (a < b).to(tl.int8)
    tl.store(C_ptr + offs, res, mask=mask)


@triton.jit
def _copy_strided_kernel(
    C_ptr,
    A_ptr,
    numel,
    shape_ptr,
    astride_ptr,
    OUT_DT: tl.constexpr,
    BLOCK: tl.constexpr,
    MAX_DIMS: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid.to(tl.int64) * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
    mask = offs < numel
    rem = offs
    a_off = tl.zeros((BLOCK,), dtype=tl.int64)
    for d in range(MAX_DIMS - 1, -1, -1):
        dim_size = tl.load(shape_ptr + d).to(tl.int64)
        a_str = tl.load(astride_ptr + d).to(tl.int64)
        coord = rem % dim_size
        rem = rem // dim_size
        a_off += coord * a_str
    c = tl.load(C_ptr + offs, mask=mask)
    tl.store(A_ptr + a_off, c.to(OUT_DT), mask=mask)


def _pad_right(seq, fill):
    seq = list(seq)
    return [fill] * (MAX_DIMS - len(seq)) + seq


_TL_DT = {
    torch.float16: tl.float16,
    torch.bfloat16: tl.bfloat16,
    torch.float32: tl.float32,
    torch.float64: tl.float64,
    torch.int8: tl.int8,
    torch.int16: tl.int16,
    torch.int32: tl.int32,
    torch.int64: tl.int64,
    torch.uint8: tl.uint8,
    torch.bool: tl.int1,
}


def lt_(A, B):
    numel = A.numel()
    if numel == 0:
        return A

    # 16-bit operands tolerate BLOCK=16384; 32-bit overflow the Ascend unified
    # buffer there, so 4-byte dtypes use 8192.
    elem_bytes = A.element_size()
    if torch.is_tensor(B):
        elem_bytes = max(elem_bytes, B.element_size())
    BLOCK = 16384 if elem_bytes <= 2 else 8192

    a_contig = A.is_contiguous()
    scalar_B = not torch.is_tensor(B)
    same_contig_B = (not scalar_B) and (A.shape == B.shape) and B.is_contiguous()

    # Fast path: single-pass persistent in-place kernel. Grid is capped at the
    # device vector-core count (this is a pure Vector comparison kernel) and the
    # kernel strides by tl.num_programs(0), so it is correct and portable. This
    # matches the reference's memory traffic exactly: read A, read B, write A,
    # with no scratch buffer and a single launch.
    if a_contig and (scalar_B or same_contig_B):
        tiles = triton.cdiv(numel, BLOCK)
        vcore = _num_vectorcore(A.device.index if A.device.index is not None else 0)
        grid = (min(tiles, vcore),)
        if scalar_B:
            _inplace_scalar_kernel[grid](A, B, numel, BLOCK=BLOCK)
        else:
            _inplace_contig_kernel[grid](A, B, numel, BLOCK=BLOCK)
        return A

    # Fallback: broadcast / non-contiguous path uses the proven two-kernel
    # compute-into-int8-buffer + strided copy-back design.
    BLOCK_STRIDED = 8192
    grid_strided = (triton.cdiv(numel, BLOCK_STRIDED),)
    out_dt = _TL_DT[A.dtype]
    C = torch.empty(A.shape, dtype=torch.int8, device=A.device)

    ndim = A.dim()
    assert ndim <= MAX_DIMS, "rank exceeds supported MAX_DIMS"
    B_exp = B.broadcast_to(A.shape)
    shape = _pad_right(A.shape, 1)
    a_strides = _pad_right(A.stride(), 0)
    b_strides = _pad_right(B_exp.stride(), 0)
    dev = A.device
    shape_t = torch.tensor(shape, dtype=torch.int64, device=dev)
    astride_t = torch.tensor(a_strides, dtype=torch.int64, device=dev)
    bstride_t = torch.tensor(b_strides, dtype=torch.int64, device=dev)
    _cmp_strided_kernel[grid_strided](
        A,
        B,
        C,
        numel,
        shape_t,
        astride_t,
        bstride_t,
        BLOCK=BLOCK_STRIDED,
        MAX_DIMS=MAX_DIMS,
    )
    _copy_strided_kernel[grid_strided](
        C,
        A,
        numel,
        shape_t,
        astride_t,
        OUT_DT=out_dt,
        BLOCK=BLOCK_STRIDED,
        MAX_DIMS=MAX_DIMS,
    )
    return A
